package com.swarmer;

import com.google.gson.annotations.SerializedName;
import lombok.EqualsAndHashCode;
import lombok.Value;
import net.runelite.client.party.messages.PartyMemberMessage;

/**
 * A swarm a party member has hit, sent before the hitsplat lands. The wave is sent along with
 * the NPC index so a party member in another raid can't hide an unrelated swarm.
 */
@Value
@EqualsAndHashCode(callSuper = true)
public class SwarmKilledMessage extends PartyMemberMessage
{
	@SerializedName("i")
	int npcIndex;
	@SerializedName("w")
	int wave;
}

package com.swarmer;

import lombok.Getter;
import lombok.RequiredArgsConstructor;

@Getter
@RequiredArgsConstructor
public enum SwarmerFont
{
	RUNESCAPE("RuneScape"),
	ARIAL("Arial"),
	CAMBRIA("Cambria"),
	ROCKWELL("Rockwell"),
	SEGOE_UI("Segoe UI"),
	TIMES_NEW_ROMAN("Times New Roman"),
	VERDANA("Verdana"),
	DIALOG("Dialog");

	private final String name;

	@Override
	public String toString()
	{
		return name;
	}
}

package com.swarmer;

import java.awt.Color;
import net.runelite.client.config.Alpha;
import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.ConfigSection;
import net.runelite.client.config.Range;

@ConfigGroup(SwarmerConfig.GROUP)
public interface SwarmerConfig extends Config
{
	String GROUP = "swarmer";

	@ConfigSection(
		name = "High waves",
		description = "Swarms from late waves that can't reach Kephri in time",
		position = 10
	)
	String highWaveSection = "highWave";

	@ConfigSection(
		name = "Wave numbers",
		description = "Wave number shown above each swarm",
		position = 20
	)
	String numberSection = "numbers";

	@ConfigSection(
		name = "Highlight",
		description = "Highlight around each swarm that's still alive and under the wave threshold",
		position = 30
	)
	String highlightSection = "highlight";

	@ConfigItem(
		keyName = "hideKilled",
		name = "Hide killed swarms",
		description = "Hide a swarm as soon as a hit on it deals damage, before the hitsplat lands",
		position = 0
	)
	default boolean hideKilled()
	{
		return true;
	}

	@ConfigItem(
		keyName = "hideHighSwarms",
		name = "Hide high wave swarms",
		description = "Hide swarms above the wave threshold",
		position = 11,
		section = highWaveSection
	)
	default boolean hideHighSwarms()
	{
		return false;
	}

	@ConfigItem(
		keyName = "hideHighNumbers",
		name = "Hide high wave numbers",
		description = "Hide wave numbers above the wave threshold",
		position = 12,
		section = highWaveSection
	)
	default boolean hideHighNumbers()
	{
		return false;
	}

	@Range(min = 1, max = 50)
	@ConfigItem(
		keyName = "phase1Threshold",
		name = "First down threshold",
		description = "Highest wave shown on Kephri's first down",
		position = 13,
		section = highWaveSection
	)
	default int phase1Threshold()
	{
		return 20;
	}

	@Range(min = 1, max = 50)
	@ConfigItem(
		keyName = "phase2Threshold",
		name = "Later downs threshold",
		description = "Highest wave shown on Kephri's later downs",
		position = 14,
		section = highWaveSection
	)
	default int phase2Threshold()
	{
		return 17;
	}

	@ConfigItem(
		keyName = "showNumbers",
		name = "Show wave numbers",
		description = "Show which wave each swarm spawned in",
		position = 21,
		section = numberSection
	)
	default boolean showNumbers()
	{
		return true;
	}

	@ConfigItem(
		keyName = "fontType",
		name = "Font",
		description = "Font of the wave numbers",
		position = 22,
		section = numberSection
	)
	default SwarmerFont fontType()
	{
		return SwarmerFont.RUNESCAPE;
	}

	@ConfigItem(
		keyName = "boldFont",
		name = "Bold",
		description = "Use a bold font",
		position = 23,
		section = numberSection
	)
	default boolean boldFont()
	{
		return true;
	}

	@Range(min = 8, max = 40)
	@ConfigItem(
		keyName = "fontSize",
		name = "Font size",
		description = "Size of the wave numbers",
		position = 24,
		section = numberSection
	)
	default int fontSize()
	{
		return 16;
	}

	@ConfigItem(
		keyName = "fontColor",
		name = "Font color",
		description = "Color of the wave numbers",
		position = 25,
		section = numberSection
	)
	default Color fontColor()
	{
		return Color.WHITE;
	}

	@ConfigItem(
		keyName = "highlight",
		name = "Highlight swarms",
		description = "Highlight swarms that are still alive and under the wave threshold",
		position = 31,
		section = highlightSection
	)
	default boolean highlight()
	{
		return false;
	}

	@ConfigItem(
		keyName = "highlightMode",
		name = "Mode",
		description = "How swarms are highlighted",
		position = 32,
		section = highlightSection
	)
	default HighlightMode highlightMode()
	{
		return HighlightMode.TRUE_TILE;
	}

	@Alpha
	@ConfigItem(
		keyName = "highlightColor",
		name = "Color",
		description = "Color of the highlight",
		position = 33,
		section = highlightSection
	)
	default Color highlightColor()
	{
		return Color.CYAN;
	}
}

package com.swarmer;

import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.Shape;
import java.awt.Stroke;
import java.awt.font.TextLayout;
import java.awt.Rectangle;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.NPC;
import net.runelite.api.Perspective;
import net.runelite.api.coords.LocalPoint;
import net.runelite.api.Point;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.OverlayUtil;
import net.runelite.client.ui.overlay.outline.ModelOutlineRenderer;

class SwarmerOverlay extends Overlay
{
	private static final Stroke OUTLINE = new BasicStroke(3);

	private final Client client;
	private final SwarmerPlugin plugin;
	private final SwarmerConfig config;
	private final ModelOutlineRenderer outlineRenderer;
	private final List<Swarm> sorted = new ArrayList<>();
	private final List<Rectangle> drawn = new ArrayList<>();

	private volatile Font font;

	@Inject
	SwarmerOverlay(Client client, SwarmerPlugin plugin, SwarmerConfig config, ModelOutlineRenderer outlineRenderer)
	{
		this.client = client;
		this.plugin = plugin;
		this.config = config;
		this.outlineRenderer = outlineRenderer;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_SCENE);
		setPriority(PRIORITY_HIGH);
	}

	void loadFont()
	{
		float size = config.fontSize();
		if (config.fontType() == SwarmerFont.RUNESCAPE)
		{
			font = (config.boldFont() ? FontManager.getRunescapeBoldFont() : FontManager.getRunescapeFont()).deriveFont(size);
		}
		else
		{
			font = new Font(config.fontType().getName(), config.boldFont() ? Font.BOLD : Font.PLAIN, (int) size);
		}
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		if (plugin.getSwarms().isEmpty())
		{
			return null;
		}

		if (config.highlight())
		{
			renderHighlights(graphics);
		}

		if (!config.showNumbers())
		{
			return null;
		}

		graphics.setFont(font);
		graphics.setStroke(OUTLINE);
		graphics.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING, RenderingHints.VALUE_TEXT_ANTIALIAS_ON);
		Color color = config.fontColor();

		// Numbers that would overlap one already drawn are moved down below it. Going in a fixed
		// order keeps each number in the same place from frame to frame.
		sorted.clear();
		sorted.addAll(plugin.getSwarms());
		sorted.sort(Comparator.comparingInt(Swarm::getWave).thenComparingInt(swarm -> swarm.getNpc().getIndex()));
		drawn.clear();
		for (Swarm swarm : sorted)
		{
			NPC npc = swarm.getNpc();
			int animation = npc.getAnimation();
			if (animation == SwarmerPlugin.ANIMATION_SWARM_DEATH || animation == SwarmerPlugin.ANIMATION_SWARM_LEAK
				|| plugin.isNumberHidden(swarm))
			{
				continue;
			}

			String text = Integer.toString(swarm.getWave());
			Point location = npc.getCanvasTextLocation(graphics, text, 0);
			if (location == null)
			{
				continue;
			}

			Shape outline = new TextLayout(text, font, graphics.getFontRenderContext())
				.getOutline(null);
			Rectangle bounds = outline.getBounds();
			bounds.translate(location.getX(), location.getY());
			bounds.grow(1, 1);
			for (int i = 0; i < drawn.size(); i++)
			{
				Rectangle other = drawn.get(i);
				if (bounds.intersects(other))
				{
					bounds.y = other.y + other.height;
					// Moving it can make it hit one that was already checked
					i = -1;
				}
			}
			drawn.add(bounds);

			int x = location.getX();
			int y = bounds.y - outline.getBounds().y + 1;
			graphics.translate(x, y);
			graphics.setColor(Color.BLACK);
			graphics.draw(outline);
			graphics.setColor(color);
			graphics.fill(outline);
			graphics.translate(-x, -y);
		}
		return null;
	}

	private void renderHighlights(Graphics2D graphics)
	{
		HighlightMode mode = config.highlightMode();
		Color color = config.highlightColor();
		Color fill = new Color(color.getRed(), color.getGreen(), color.getBlue(), color.getAlpha() / 5);
		for (Swarm swarm : plugin.getSwarms())
		{
			NPC npc = swarm.getNpc();
			int animation = npc.getAnimation();
			if (animation == SwarmerPlugin.ANIMATION_SWARM_DEATH || animation == SwarmerPlugin.ANIMATION_SWARM_LEAK
				|| plugin.isHighlightHidden(swarm))
			{
				continue;
			}

			Shape shape = null;
			switch (mode)
			{
				case TRUE_TILE:
					// The tile the server has it on, rather than where it's drawn mid-walk
					LocalPoint tile = LocalPoint.fromWorld(npc.getWorldView(), npc.getWorldLocation());
					if (tile != null)
					{
						int size = npc.getComposition().getSize();
						shape = Perspective.getCanvasTileAreaPoly(client, tile.plus(
							(size - 1) * Perspective.LOCAL_HALF_TILE_SIZE, (size - 1) * Perspective.LOCAL_HALF_TILE_SIZE), size);
					}
					break;
				case TILE:
					shape = npc.getCanvasTilePoly();
					break;
				case HULL:
					shape = npc.getConvexHull();
					break;
				case OUTLINE:
					outlineRenderer.drawOutline(npc, 2, color, 4);
					break;
			}

			if (shape != null)
			{
				OverlayUtil.renderPolygon(graphics, shape, color, fill, new BasicStroke(2));
			}
		}
		graphics.setStroke(OUTLINE);
	}
}

package com.swarmer;

import lombok.AccessLevel;
import lombok.Getter;
import lombok.Setter;
import net.runelite.api.NPC;

@Getter
@Setter(AccessLevel.PACKAGE)
class Swarm
{
	private final NPC npc;
	private final int wave;
	// Ticks since the swarm was hidden as dead, or -1 while it isn't
	private int hiddenTicks = -1;

	Swarm(NPC npc, int wave)
	{
		this.npc = npc;
		this.wave = wave;
	}

	boolean isKilled()
	{
		return hiddenTicks >= 0;
	}
}

package com.swarmer;

import com.google.common.collect.ImmutableSet;
import com.google.inject.Provides;
import java.util.Collection;
import java.util.EnumMap;
import java.util.HashMap;
import java.util.Map;
import java.util.Set;
import javax.inject.Inject;
import net.runelite.api.Actor;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.NPC;
import net.runelite.api.Player;
import net.runelite.api.PlayerComposition;
import net.runelite.api.Renderable;
import net.runelite.api.Skill;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.events.AnimationChanged;
import net.runelite.api.events.ChatMessage;
import net.runelite.api.events.FakeXpDrop;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.HitsplatApplied;
import net.runelite.api.events.NpcDespawned;
import net.runelite.api.events.NpcSpawned;
import net.runelite.api.events.StatChanged;
import net.runelite.api.gameval.AnimationID;
import net.runelite.api.gameval.ItemID;
import net.runelite.api.gameval.NpcID;
import net.runelite.api.kit.KitType;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.callback.Hooks;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.party.PartyMember;
import net.runelite.client.party.PartyService;
import net.runelite.client.party.WSClient;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.overlay.OverlayManager;

@PluginDescriptor(
	name = "Swarmer",
	description = "Hides scarab swarms at Kephri as soon as they're hit",
	tags = {"toa", "tombs", "amascut", "kephri", "swarm", "scarab", "death", "indicator", "hide", "highlight", "party"}
)
public class SwarmerPlugin extends Plugin
{
	private static final int KEPHRI_REGION = 14164;
	private static final int ANIMATION_KEPHRI_DOWN = 9579;
	private static final int ANIMATION_KEPHRI_UP = 9581;
	static final int ANIMATION_SWARM_LEAK = 9607;
	static final int ANIMATION_SWARM_DEATH = 9608;
	// A hidden swarm that still has health this many ticks later was predicted wrong, so it's shown again
	private static final int HIDDEN_TIMEOUT_TICKS = 5;
	private static final String ROOM_FAIL_MESSAGE = "Your party failed to complete";

	private static final Set<Integer> CHINCHOMPAS = ImmutableSet.of(
		ItemID.CHINCHOMPA_CAPTURED, ItemID.CHINCHOMPA_BIG_CAPTURED, ItemID.CHINCHOMPA_BLACK);

	// The special attack can hit other targets without touching the one being attacked
	private static final Set<Integer> UNRELIABLE_TARGET_WEAPONS = ImmutableSet.of(ItemID.DINHS_BULWARK);

	@Inject
	private Client client;

	@Inject
	private ClientThread clientThread;

	@Inject
	private Hooks hooks;

	@Inject
	private OverlayManager overlayManager;

	@Inject
	private SwarmerOverlay overlay;

	@Inject
	private SwarmerConfig config;

	@Inject
	private PartyService partyService;

	@Inject
	private WSClient wsClient;

	// Swarms spawned since Kephri went down, by NPC index
	private final Map<Integer, Swarm> swarms = new HashMap<>();
	private final Hooks.RenderableDrawListener drawListener = this::shouldDraw;

	private boolean inRoom;
	private boolean kephriDowned;
	private int downs;
	private int wave;
	private int lastSpawnTick;
	// Last seen XP in each skill, to spot XP drops
	private final Map<Skill, Integer> xp = new EnumMap<>(Skill.class);

	// Read on every draw call, so cached instead of going through the config proxy
	private boolean hideKilled;
	private boolean hideHighSwarms;
	private boolean hideHighNumbers;
	private int phase1Threshold;
	private int phase2Threshold;

	@Provides
	SwarmerConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(SwarmerConfig.class);
	}

	@Override
	protected void startUp()
	{
		loadConfig();
		overlay.loadFont();
		reset();
		xp.clear();
		inRoom = false;
		wsClient.registerMessage(SwarmKilledMessage.class);
		hooks.registerRenderableDrawListener(drawListener);
		overlayManager.add(overlay);
		clientThread.invoke(() ->
		{
			if (client.getGameState() == GameState.LOGGED_IN)
			{
				loadXp();
				inRoom = isInKephriRoom();
			}
		});
	}

	@Override
	protected void shutDown()
	{
		overlayManager.remove(overlay);
		hooks.unregisterRenderableDrawListener(drawListener);
		wsClient.unregisterMessage(SwarmKilledMessage.class);
		clientThread.invoke(this::reset);
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (SwarmerConfig.GROUP.equals(event.getGroup()))
		{
			loadConfig();
			overlay.loadFont();
		}
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		GameState state = event.getGameState();
		if (state == GameState.LOGIN_SCREEN || state == GameState.HOPPING)
		{
			xp.clear();
		}
	}

	@Subscribe
	public void onGameTick(GameTick event)
	{
		boolean now = isInKephriRoom();
		if (now != inRoom)
		{
			inRoom = now;
			reset();
			return;
		}

		for (Swarm swarm : swarms.values())
		{
			if (!swarm.isKilled())
			{
				continue;
			}

			swarm.setHiddenTicks(swarm.getHiddenTicks() + 1);
			if (swarm.getHiddenTicks() > HIDDEN_TIMEOUT_TICKS && swarm.getNpc().getHealthRatio() != 0)
			{
				// Not dead after all, most likely an XP drop that came from a different target
				swarm.setHiddenTicks(-1);
				swarm.getNpc().setDead(false);
			}
		}
	}

	@Subscribe
	public void onChatMessage(ChatMessage event)
	{
		if (inRoom && event.getType() == ChatMessageType.GAMEMESSAGE && event.getMessage().startsWith(ROOM_FAIL_MESSAGE))
		{
			reset();
		}
	}

	@Subscribe
	public void onAnimationChanged(AnimationChanged event)
	{
		if (!inRoom || !(event.getActor() instanceof NPC))
		{
			return;
		}

		NPC npc = (NPC) event.getActor();
		if (npc.getId() != NpcID.TOA_KEPHRI_BOSS_SHIELDED && npc.getId() != NpcID.TOA_KEPHRI_BOSS_WEAK)
		{
			return;
		}

		if (!kephriDowned && npc.getAnimation() == ANIMATION_KEPHRI_DOWN)
		{
			kephriDowned = true;
			downs++;
			wave = 0;
			lastSpawnTick = -1;
		}
		else if (kephriDowned && npc.getAnimation() == ANIMATION_KEPHRI_UP)
		{
			kephriDowned = false;
		}
	}

	@Subscribe
	public void onNpcSpawned(NpcSpawned event)
	{
		NPC npc = event.getNpc();
		if (!inRoom || !kephriDowned || npc.getId() != NpcID.TOA_KEPHRI_SHIELD_SCARAB)
		{
			return;
		}

		// Every swarm spawned on the same tick belongs to the same wave
		int tick = client.getTickCount();
		if (tick != lastSpawnTick)
		{
			wave++;
			lastSpawnTick = tick;
		}

		swarms.put(npc.getIndex(), new Swarm(npc, wave));
	}

	@Subscribe
	public void onNpcDespawned(NpcDespawned event)
	{
		Swarm swarm = getSwarm(event.getNpc());
		if (swarm != null)
		{
			swarms.remove(swarm.getNpc().getIndex());
		}
	}

	@Subscribe
	public void onHitsplatApplied(HitsplatApplied event)
	{
		if (!(event.getActor() instanceof NPC) || event.getHitsplat().getAmount() <= 0)
		{
			return;
		}

		// Any damage kills a swarm, so a landed hit from anyone, including players without the plugin, is a kill
		Swarm swarm = getSwarm((NPC) event.getActor());
		if (swarm != null)
		{
			markKilled(swarm);
		}
	}

	@Subscribe
	public void onStatChanged(StatChanged event)
	{
		Integer previous = xp.put(event.getSkill(), event.getXp());
		if (previous != null && event.getXp() > previous)
		{
			processXpDrop();
		}
	}

	@Subscribe
	public void onFakeXpDrop(FakeXpDrop event)
	{
		// Sent instead of a stat change once a skill is at 200m XP
		processXpDrop();
	}

	private void loadXp()
	{
		for (Skill skill : Skill.values())
		{
			xp.put(skill, client.getSkillExperience(skill));
		}
	}

	/**
	 * Swarms have -100 defence, so every hit on them lands and kills one. Killing one gives a
	 * single XP in the attack style's skill and no Hitpoints XP, so an XP drop in any skill while
	 * attacking a swarm means it's dead before the hitsplat lands.
	 */
	private void processXpDrop()
	{
		if (swarms.isEmpty())
		{
			return;
		}

		Player player = client.getLocalPlayer();
		Actor target = player == null ? null : player.getInteracting();
		Swarm swarm = target instanceof NPC ? getSwarm((NPC) target) : null;
		PlayerComposition composition = player == null ? null : player.getPlayerComposition();
		if (swarm == null || composition == null)
		{
			return;
		}

		int weapon = composition.getEquipmentId(KitType.WEAPON);
		if (UNRELIABLE_TARGET_WEAPONS.contains(weapon))
		{
			return;
		}

		int animation = player.getAnimation();
		if (CHINCHOMPAS.contains(weapon)
			|| animation == AnimationID.ZAROS_VERTICAL_CASTING
			|| animation == AnimationID.ZAROS_VERTICAL_CASTING_WALKMERGE)
		{
			// Chinchompas and burst or barrage spells hit everything in the 3x3 around the target
			WorldPoint centre = swarm.getNpc().getWorldLocation();
			for (Swarm other : swarms.values())
			{
				if (other.getNpc().getWorldLocation().distanceTo(centre) <= 1)
				{
					sendKill(other);
				}
			}
		}
		else
		{
			sendKill(swarm);
		}
	}

	private void sendKill(Swarm swarm)
	{
		if (swarm.isKilled())
		{
			return;
		}

		if (partyService.isInParty())
		{
			partyService.send(new SwarmKilledMessage(swarm.getNpc().getIndex(), swarm.getWave()));
		}
		markKilled(swarm);
	}

	@Subscribe
	public void onSwarmKilledMessage(SwarmKilledMessage message)
	{
		PartyMember local = partyService.getLocalMember();
		if (local != null && local.getMemberId() == message.getMemberId())
		{
			return;
		}

		clientThread.invoke(() ->
		{
			// Only trust it if it matches a swarm from the same wave in this room
			Swarm swarm = swarms.get(message.getNpcIndex());
			if (swarm != null && swarm.getWave() == message.getWave())
			{
				markKilled(swarm);
			}
		});
	}

	private void markKilled(Swarm swarm)
	{
		if (swarm.isKilled())
		{
			return;
		}

		swarm.setHiddenTicks(0);
		if (hideKilled)
		{
			// Lets other plugins, like NPC indicators, treat it as dead too
			swarm.getNpc().setDead(true);
		}
	}

	private Swarm getSwarm(NPC npc)
	{
		Swarm swarm = swarms.get(npc.getIndex());
		return swarm != null && swarm.getNpc() == npc ? swarm : null;
	}

	Collection<Swarm> getSwarms()
	{
		return swarms.values();
	}

	boolean isHidden(Swarm swarm)
	{
		return (hideKilled && swarm.isKilled()) || (hideHighSwarms && isHighWave(swarm));
	}

	boolean isNumberHidden(Swarm swarm)
	{
		return isHidden(swarm) || (hideHighNumbers && isHighWave(swarm));
	}

	boolean isHighlightHidden(Swarm swarm)
	{
		// Only swarms still worth attacking are highlighted
		return swarm.isKilled() || isHighWave(swarm);
	}

	private boolean isHighWave(Swarm swarm)
	{
		return swarm.getWave() > (downs <= 1 ? phase1Threshold : phase2Threshold);
	}

	private boolean shouldDraw(Renderable renderable, boolean drawingUI)
	{
		if (swarms.isEmpty() || !(renderable instanceof NPC))
		{
			return true;
		}

		Swarm swarm = getSwarm((NPC) renderable);
		return swarm == null || !isHidden(swarm);
	}

	private boolean isInKephriRoom()
	{
		Player player = client.getLocalPlayer();
		return player != null
			&& WorldPoint.fromLocalInstance(client, player.getLocalLocation()).getRegionID() == KEPHRI_REGION;
	}

	private void loadConfig()
	{
		hideKilled = config.hideKilled();
		hideHighSwarms = config.hideHighSwarms();
		hideHighNumbers = config.hideHighNumbers();
		phase1Threshold = config.phase1Threshold();
		phase2Threshold = config.phase2Threshold();
	}

	private void reset()
	{
		for (Swarm swarm : swarms.values())
		{
			if (swarm.isKilled())
			{
				swarm.getNpc().setDead(false);
			}
		}
		swarms.clear();
		kephriDowned = false;
		downs = 0;
		wave = 0;
		lastSpawnTick = -1;
	}
}

